using IOViewer.Exporters;
using IOScene;

namespace DwgIO.Scene;

/// <summary>
/// Exports a drawing as a standalone interactive 3D HTML viewer: one self-contained file with the scene and the
/// WebGL viewer runtime embedded, no server and no external scripts. The viewer is generated by
/// <see href="https://github.com/IOExtend/IOViewer">IOViewer</see> from the IOScene scene document, so the
/// drawing shows exactly what the scene JSON and the OBJ/GLB exports describe.
/// </summary>
public static class DwgViewerExport
{
    /// <summary>Converts the drawing and writes it to a standalone interactive HTML viewer file.</summary>
    /// <param name="document">The drawing, for example from <see cref="DwgDocument.Open(string, DwgReaderOptions?)"/>.</param>
    /// <param name="htmlPath">Path to the HTML file.</param>
    /// <param name="options">Scene conversion options; null uses the defaults.</param>
    /// <param name="viewerOptions">Viewer options (title, initial mode, vertex budget); null uses the defaults.</param>
    /// <returns>The conversion report. <see cref="DwgSceneResult.Document"/> is the scene the viewer embeds.</returns>
    public static DwgSceneResult SaveViewer(
        DwgDocument document,
        string htmlPath,
        DwgSceneOptions? options = null,
        HtmlViewerOptions? viewerOptions = null)
    {
        var result = DwgSceneReader.Read(document, ViewerOptionsFor(document, htmlPath, options));
        WriteViewer(result.Document, htmlPath, viewerOptions);
        return result;
    }

    /// <summary>Writes a scene to a standalone interactive HTML viewer file.</summary>
    /// <param name="scene">The scene to embed.</param>
    /// <param name="htmlPath">Path to the HTML file.</param>
    /// <param name="viewerOptions">Viewer options; null uses the defaults.</param>
    public static void WriteViewer(SceneDocument scene, string htmlPath, HtmlViewerOptions? viewerOptions = null)
    {
        ArgumentNullException.ThrowIfNull(scene);
        ArgumentException.ThrowIfNullOrEmpty(htmlPath);
        if (viewerOptions is null)
        {
            // Default options take their title from the scene; a caller's options are respected as given,
            // with an empty title filled from the scene.
            viewerOptions = new HtmlViewerOptions { Title = scene.Title };
        }
        else if (string.IsNullOrEmpty(viewerOptions.Title))
        {
            viewerOptions.Title = scene.Title;
        }

        HtmlViewerExporter.Save(scene, htmlPath, viewerOptions);
    }

    private static DwgSceneOptions ViewerOptionsFor(DwgDocument document, string path, DwgSceneOptions? options)
    {
        if (options?.ModelKey is { Length: > 0 })
        {
            return options;
        }

        // The export file name doubles as the model key; a document from memory falls back to it.
        return new DwgSceneOptions
        {
            LengthUnit = options?.LengthUnit ?? "m",
            ModelKey = Path.GetFileName(path),
        };
    }
}
